const $=id=>document.getElementById(id);
const S={concurrency:null,page:'new',brands:[],fields:{},required:[],optional:[],settings:{},brand:'',step:1,selected:[],file:null,inputMode:'excel',validation:null,wizardBusy:false,jobId:localStorage.getItem('crawlerJob'),job:null,history:[],queue:[],queueOffset:0,reviewRows:[],reviewOffset:0,item:null,reviewId:null,reviewTab:'images',queueTask:null,queueKey:'',reviewKey:'',busy:false,logOffset:0};
const titles={new:'새 크롤링',monitor:'실행 모니터',review:'결과 검수',history:'작업 이력',admin:'관리자',mapping:'색상 매핑'};
const stateNames={saving:'결과 저장 중',running:'수집 중',pausing:'일시정지 대기',paused:'일시정지',stopping:'중지 중',stopped:'중지됨',completed:'완료',error:'오류',interrupted:'중단됨',WAITING:'대기',RUNNING:'수집 중',SUCCESS:'성공',FAILED:'실패',CANCELLED:'중지',SKIPPED:'제외',mapping:'매핑 대기',normal:'정상',warning:'확인 필요'};
