const active=()=>S.job&&['running','pausing','paused','stopping','saving'].includes(S.job.state);
function el(tag,text,cls){let n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function hide(id,value){$(id).classList.toggle('hidden',value)}
function toast(message,error=false){$('toast').textContent=message;$('toast').className='toast'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>hide('toast',true),5500)}
async function api(path,data){const r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Portal-Token':window.PORTAL_TOKEN},body:JSON.stringify(data)});let d;try{d=await r.json()}catch{throw Error('서버 응답을 읽을 수 없습니다. Crawler Hub 실행 상태를 확인하세요.')}if(!r.ok)throw Error(d.error||'요청에 실패했습니다.');return d}
function run(fn){return async(...args)=>{try{return await fn(...args)}catch(e){toast(e.message,true)}}}
function status(value){const type=['completed','SUCCESS','normal'].includes(value)?'success':['error','FAILED'].includes(value)?'error':['warning','paused','pausing','interrupted'].includes(value)?'warning':['WAITING','CANCELLED','SKIPPED','stopped'].includes(value)?'subtle':'';return el('span',stateNames[value]||value,'status '+type)}
function time(seconds){if(seconds===null||seconds===undefined)return '—';seconds=Math.round(seconds);return seconds<60?seconds+'초':Math.floor(seconds/60)+'분 '+seconds%60+'초'}
function date(value){if(!value)return '이전 버전 작업';return new Date(value).toLocaleString('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function brandLabel(b){if(!b)return '';const source=(b.crawl_source||'소스 미지정').replace(/\s*[·|]\s*수동 매핑 샘플/g,'').trim();return b.name+' ('+source+')'}
function brand(){return S.brands.find(b=>b.id===S.brand)||S.brands[0]}
function link(url,label,cls='secondary'){const a=el('a',label,cls);a.href=url;if(/^\/api\/jobs\/[a-f0-9]{32}\/(?:export|download|original)$/.test(url)){a.download='crawler-result.xlsx'}else{a.target='_blank';a.rel='noopener noreferrer'}return a}
function safeUrl(url){if(/^\/api\/jobs\/[a-f0-9]{32}\/image\?path=/.test(url))return true;return /^https?:\/\//i.test(url)||/^\/sample\/\d+\/\d+$/.test(url)}
function button(text,fn,cls='secondary'){const b=el('button',text,cls);b.onclick=run(fn);return b}
function metric(label,value,note='',cls=''){const d=el('div',undefined,'metric '+cls);d.append(el('span',label),el('strong',value),el('small',note));return d}
function empty(container,title,description){const d=el('div',undefined,'empty-state');d.append(el('span','▧'),el('h2',title),el('p',description));container.replaceChildren(d)}
function skeleton(container){container.replaceChildren(el('div',undefined,'skeleton'),el('div',undefined,'skeleton'),el('div',undefined,'skeleton'))}
async function navigate(page){if(S.page==='mapping'&&page!=='mapping')await saveMappingDrafts();if(!titles[page])page='new';S.page=page;Object.keys(titles).forEach(k=>hide('page-'+k,k!==page));$('pageTitle').textContent=titles[page];document.querySelectorAll('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));history.replaceState(null,'','#'+page);if(page==='history')await loadHistory();if(page==='new'){await refreshBrands();renderWizard();}if(page==='admin')await loadAdmin();if(page==='mapping')await loadMapping();if(page==='monitor'){await openMonitorPage();}if(page==='review'){await loadJobChoices('review');S.reviewKey='';await loadReview(true)} }
function navigation(){for(const [key,title] of Object.entries(titles)){if(key==='mapping')continue;const b=el('button');b.dataset.page=key;b.setAttribute('aria-label',title);b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[key]||icons[key==='logs'?'history':'settings'])+'</svg>';b.append(el('span',title));b.onclick=run(()=>navigate(key));$('navigation').append(b)}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=run(()=>navigate(b.dataset.go)))}
async function refreshBrands(){const meta=await api('/api/brands');S.brands=meta.brands;S.concurrency=meta.concurrency;renderConcurrency();if(!S.brands.some(b=>b.id===S.brand))S.brand=S.brands[0]?.id||'';}
async function loadHistory(){await refreshConcurrency();S.history=await api('/api/history');renderHistory()}
function renderHistory(){const search=$('historySearch').value.trim().toLowerCase();const rows=S.history.filter(x=>(x.brand+' '+x.name).toLowerCase().includes(search));$('historyCount').textContent=rows.length+'개 작업';$('historyRows').replaceChildren();for(const j of rows){let tr=el('tr'),title=el('td'),b=el('b',j.name||j.brand+' 수집');title.append(b,el('small',date(j.created_at)+(j.demo?' · 샘플':'')));const state=el('td');state.append(status(j.state));let fields=el('td',(j.selected||[]).map(k=>S.fields[k]).join(' · ')||'필수 항목','history-fields');let actions=el('td'),wrap=el('div',undefined,'history-actions');const continueButton=button('이어하기',async()=>{await jobAction('continue',j.id);await openJob(j.id,'monitor')}),retryButton=button('실패 재실행',async()=>{await jobAction('retry-failed',j.id);await openJob(j.id,'monitor')});const reason=S.concurrency?.availability?.[j.brand_id]?.reason||'';continueButton.disabled=!!reason||!j.can_continue||['running','paused','pausing','saving','stopping'].includes(j.state);retryButton.disabled=!!reason||!j.can_retry||['running','paused','pausing','saving','stopping'].includes(j.state);continueButton.title=retryButton.title=reason;wrap.append(continueButton,retryButton,button('검수',()=>openJob(j.id,'review')),link('/api/jobs/'+j.id+'/export','엑셀 ↓'),button('폴더 ↗',()=>jobAction('open-folder',j.id)));if(j.mapping_mode==='manual'){const map=button(j.mapping_finalized?'✓ 매핑 완료 · 수정':'색상 매핑하기',()=>openMapping(j.id));map.disabled=['running','paused','pausing','saving','stopping'].includes(j.state);wrap.append(map)}actions.append(wrap);tr.append(title,el('td',j.brand),state,el('td',String(j.total)),el('td',(j.success??Math.max(0,(j.done||0)-(j.failed||0)))+' / '+(j.failed||0)),fields,el('td',time(j.elapsed)),actions);$('historyRows').append(tr)}if(!rows.length){const tr=el('tr'),td=el('td','표시할 작업이 없습니다.');td.colSpan=8;tr.append(td);$('historyRows').append(tr)}}
function brandBlockReason(b=brand()){if(!b)return '브랜드를 선택해주세요.';if(!b.available)return '크롤러 파일을 확인해주세요.';return S.concurrency?.availability?.[b.id]?.reason||(S.concurrency?'':'실행 가능 상태 확인 중입니다.')}
function renderConcurrency(){
 const data=S.concurrency;if(!data)return;
 for(const id of ['newConcurrencyPanel','monitorConcurrencyPanel']){const panel=$(id);if(!panel)continue;panel.replaceChildren();const head=el('div',undefined,'execution-heading');head.append(el('strong','동시 실행 '+data.active.length+' / '+data.limit),el('span','같은 사이트·크롬 사용 중복은 자동으로 제한됩니다.','description'));panel.append(head);const list=el('div',undefined,'execution-jobs');for(const job of data.active){const item=button('',()=>openJob(job.id,'monitor'),'execution-job'+(job.id===S.jobId?' selected':''));item.append(el('b',job.name),el('small',job.brand+' · '+(stateNames[job.state]||job.state)));list.append(item)}if(data.active.length)panel.append(list);else panel.append(el('p','지금 새 작업을 시작할 수 있습니다.','description'));if(data.active.some(j=>['paused','pausing','stopping'].includes(j.state)))panel.append(el('p','일시정지·중지 처리 중인 작업도 사용 중으로 계산합니다. 작업이 완전히 끝나면 제한이 해제됩니다.','description'));}
 const reason=brandBlockReason();if($('newExecutionBlock')){$('newExecutionBlock').textContent=reason;hide('newExecutionBlock',!reason)}
}
async function refreshConcurrency(){const data=await api('/api/concurrency'),changed=JSON.stringify(data.availability)!==JSON.stringify(S.concurrency?.availability);S.concurrency=data;renderConcurrency();if(S.page==='new'){if(changed)renderBrands();$('nextStep').disabled=!!S.wizardBusy||!!brandBlockReason();}if(S.page==='history'&&changed)renderHistory();}
function selectBrand(id){const reason=brandBlockReason(S.brands.find(b=>b.id===id));if(reason){toast(reason,true);return}S.brand=id;S.validation=null;renderBrands();renderGuide();renderSummary();renderFields();renderConcurrency();$('nextStep').disabled=!!brandBlockReason()}
function renderBrands(){const query=$('brandSearch').value.toLowerCase(),recent=S.settings.recent_brands||[];let rows=[...S.brands].sort((a,b)=>{const ai=recent.indexOf(a.id),bi=recent.indexOf(b.id);return (ai<0?99:ai)-(bi<0?99:bi)});$('brandCards').replaceChildren();if(!S.brands.length){empty($('brandCards'),'등록된 브랜드가 없습니다','관리자에서 새 브랜드를 추가하세요.');$('brandCards').append(button('브랜드 등록하기',()=>navigate('admin'),'primary'));}for(const b of rows.filter(b=>brandLabel(b).toLowerCase().includes(query))){let n=button('',()=>selectBrand(b.id),'brand-card'+(b.id===S.brand?' selected':''));const reason=brandBlockReason(b);n.disabled=!!reason;n.title=reason;if(b.image_mode==='local')n.append(el('span','이미지 저장','image-save-badge'));if(b.mapping_mode==='manual')n.append(el('span','색상 매핑 필요','mapping-required-badge'));n.append(el('b',brandLabel(b)),el('small',reason||b.category,reason?'execution-block-reason':''));if(recent.includes(b.id))n.append(el('span','최근 사용','recent-label'));$('brandCards').append(n)}}
function renderGuide(){const b=brand();if(!b){$('collectionLevel').textContent='브랜드 등록 필요';$('guideShort').replaceChildren(el('p','등록된 브랜드가 없습니다. 관리자에서 새 브랜드를 등록하세요.'));$('guideDetail').replaceChildren(el('p','브랜드 등록 후 입력 가이드가 표시됩니다.'));return}const g=b.guide;$('collectionLevel').textContent=b.interface==='portal_v1'?'LEVEL 1 · 선택 항목 실제 수집':'기존 샘플 · 교체 대상';$('collectionNotice').textContent=b.interface==='portal_v1'?'선택 항목을 크롤러에 전달합니다. 미선택 항목의 요청·파싱·이미지 처리·상세 생성은 SDK 크롤러가 단계별로 생략합니다.':'기존 크롤러 호환 모드는 전체 수집 후 출력에 선택 항목을 적용합니다. 실제 수집 생략은 관리자에서 새 Level 1 규약으로 수정한 브랜드부터 지원합니다.';$('guideShort').replaceChildren();let detail=el('div');detail.append(el('strong',brandLabel(b)+' 입력 가이드'),el('div',g.format),el('code',g.example));$('guideShort').append(el('b','ⓘ'),detail);$('guideDetail').replaceChildren(el('p',g.format));$('guideDetail').append(button(g.example,()=>{addExample(g.example);S.step=2;renderWizard()},'text-button'));$('guideDetail').append(el('p',g.notes),el('p',g.method),el('p','필수 열 · '+g.required_columns.join(', ')),el('p','잘못된 예 · '+g.invalid_examples.join(', ')),el('p',g.validation_note));}
function inputData(){if(!brand())throw Error('관리자에서 브랜드를 먼저 등록하세요.');if(S.inputMode==='excel'&&!S.file)throw Error('엑셀 파일을 먼저 선택해주세요.');return {brand:S.brand,codes:$('codes').value,file:S.inputMode==='excel'?S.file:null,demo:false,selected:S.selected,name:$('jobName').value}}
function addExample(code){$('codes').value=[$('codes').value.trim(),code].filter(Boolean).join('\n');S.inputMode='direct';renderInputMode();inputChanged()}
function inputChanged(){S.validation=null;const codes=$('codes').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);$('inputCount').textContent=codes.length+'개 품번 · 중복 '+(codes.length-new Set(codes).size)+'개';$('deduplicateCodes').disabled=codes.length===new Set(codes).size;$('deduplicateFile').disabled=true;$('validationResult').replaceChildren();renderSummary()}
function renderInputMode(reset=true){hide('directInput',S.inputMode!=='direct');hide('excelInput',S.inputMode!=='excel');$('directTab').classList.toggle('selected',S.inputMode==='direct');$('uploadTab').classList.toggle('selected',S.inputMode==='excel');if(reset)S.validation=null;renderSummary()}
async function validate(){const result=await api('/api/validate',inputData());S.validation=result;$('deduplicateFile').disabled=!result.duplicates;let box=el('div',undefined,result.valid?'success-box':'warning-box');box.append(el('b',result.total+'개 품번 · 중복 '+result.duplicates+'개 · 형식 주의 '+result.warning_count+'개'));if(result.missing_columns.length)box.append(el('p','필수 열 없음: '+result.missing_columns.join(', ')));for(const row of [...result.errors,...result.warnings].slice(0,6))box.append(el('div',row.row+'행 / '+row.code+' · '+row.message));box.append(el('div',result.notice));$('validationResult').replaceChildren(box);renderSummary();return result}
function renderWizard(){renderInputMode(false);for(let i=1;i<=3;i++)hide('step'+i,S.step!==i);$('stepper').replaceChildren();['브랜드 선택','품번 입력 및 검증','수집 항목 및 실행'].forEach((title,i)=>{const d=el('div',undefined,i+1===S.step?'current':i+1<S.step?'complete':'');d.append(el('b',i+1<S.step?'✓':String(i+1)),el('span',title));$('stepper').append(d)});$('prevStep').disabled=S.step===1;$('nextStep').textContent=S.wizardBusy?'처리 중…':S.step===3?'크롤링 시작 →':'다음 단계 →';$('nextStep').disabled=!!S.wizardBusy||!!brandBlockReason();$('stepHint').textContent=S.step+' / 3 단계';renderBrands();renderGuide();renderFields();renderSummary();renderConcurrency()}
function renderFields(){const b=brand();if(!b){$('requiredFields').replaceChildren();$('optionalFields').replaceChildren();$('columnPreview').replaceChildren();return}for(const [keys,id,required] of [[S.required,'requiredFields',true],[S.optional,'optionalFields',false]]){$(id).replaceChildren();for(const key of keys){const cap=b.fields[key],label=el('label',undefined,'field-option'+(!cap.supported?' unsupported':'')),c=el('input');c.type='checkbox';c.checked=required||S.selected.includes(key)&&cap.supported;c.disabled=required||!cap.supported;c.onchange=()=>{S.selected=c.checked?[...new Set([...S.selected,key])]:S.selected.filter(x=>x!==key);S.validation=null;renderSummary();renderColumns();persistSelection()};const text=el('span',S.fields[key]+(required?' · 필수':''));text.append(el('small',!cap.supported?'수집 불가 · '+(cap.reason||'독립 결과 컬럼 없음'):'결과 컬럼 지원 · 상품별 누락 가능'));label.append(c,text);$(id).append(label)}}renderColumns()}
function renderColumns(){const b=brand();if(!b)return;const keys=[...S.required,...S.selected.filter(k=>b.fields[k].supported)],headers=b.output_headers.filter(h=>keys.includes(b.column_fields[h])||b.extensions.includes(h));for(const k of S.required)if(!headers.some(h=>b.column_fields[h]===k))headers.push(S.fields[k]);$('columnPreview').replaceChildren(...headers.map(h=>el('span',h)));const missing=S.required.filter(k=>!b.fields[k].supported);$('unsupportedWarning').replaceChildren();if(missing.length)$('unsupportedWarning').append(el('div','필수 항목 미지원: '+missing.map(k=>S.fields[k]).join(', ')+' · 값을 임의로 만들지 않으며 결과에는 빈 셀과 누락 안내를 제공합니다.','warning-box'))}
function renderSummary(){const b=brand();if(!b){$('creationSummary').replaceChildren();$('newDirectory').textContent='';return}const sites=[...new Set((b.execution_resources?.sites||[]).map(site=>site==='naver-shopping'?'shopping.naver.com':site))];$('summaryMode').textContent='실제 크롤링';const list=[['브랜드',b.name],['사이트 이름',b.crawl_source||'미등록'],['사이트 링크',sites],['수집 항목',S.required.concat(S.selected.filter(k=>b.fields[k].supported)).map(k=>S.fields[k]).join(' · ')]];$('creationSummary').replaceChildren();for(const [key,value] of list){const dd=el('dd');if(Array.isArray(value)){if(!value.length)dd.textContent='등록된 링크 없음';for(const site of value){if(/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(site))dd.append(link('https://'+site,site+' ↗','crawler-site-link'));}}else dd.textContent=value;$('creationSummary').append(el('dt',key),dd)}$('newDirectory').textContent=S.settings.directory||''}
async function deduplicateInput(){if(S.inputMode==='direct'){const codes=$('codes').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),unique=[...new Set(codes)];$('codes').value=unique.join('\n');inputChanged();toast('중복 품번 '+(codes.length-unique.length)+'개를 제거했습니다.');return}const result=await api('/api/deduplicate',inputData());S.file=result.file;S.validation=null;await validate();toast('중복 품번 '+result.removed+'개를 제거했습니다. 첫 번째 행의 데이터를 유지합니다.')}

async function nextStep(){if(S.wizardBusy)return;S.wizardBusy=true;$('nextStep').disabled=true;$('nextStep').textContent='처리 중…';try{return await advanceStep()}finally{S.wizardBusy=false;$('nextStep').textContent=S.step===3?'크롤링 시작 →':'다음 단계 →';$('nextStep').disabled=!!brandBlockReason()}}
async function advanceStep(){if(S.step===3)await refreshConcurrency();const reason=brandBlockReason();if(reason)throw Error(reason);if(S.step===1){S.step=2;renderWizard();return}if(S.step===2){const v=S.validation||await validate();if(!v.valid)return toast('입력 오류와 필수 열을 확인해주세요.',true);S.step=3;renderWizard();return}const v=S.validation||await validate();if(!v.valid)throw Error('입력 데이터를 다시 확인해주세요.');$('nextStep').disabled=true;try{const d=await api('/api/jobs',inputData());S.settings=await api('/api/settings');resetNewForm();await openJob(d.id,'monitor');toast('크롤링 작업을 시작했습니다.')}finally{await refreshConcurrency().catch(()=>{});$('nextStep').disabled=!!brandBlockReason()}}
async function openJob(id,page='review'){const request=S.openJobRequest=(S.openJobRequest||0)+1;S.jobId=id;localStorage.setItem('crawlerJob',id);S.reviewId=null;S.item=null;$('reviewSearch').value='';$('reviewFilter').value='';S.reviewOffset=S.queueOffset=S.logOffset=0;S.queueKey=S.reviewKey='';const job=await api('/api/jobs/'+id);if(request!==S.openJobRequest||id!==S.jobId)return;S.job=job;if(page==='monitor')S.monitorRequestedId=id;renderHeader();await navigate(page)}
function renderHeader(){const local=S.job?.image_mode==='local'&&S.job?.mapping_finalized;hide('reviewMainImageFolder',!local);hide('reviewAdditionalImageFolder',!local);hide('reviewDetailImageFolder',!local||!S.job?.detail_image_ready);hide('reviewImagesZip',!local);$('reviewImagesZip').href='/api/jobs/'+S.jobId+'/images-zip';for(const id of ['reviewMapping','monitorMapping']){hide(id,S.job?.mapping_mode!=='manual');$(id).disabled=active();$(id).textContent=S.job?.mapping_finalized?'✓ 매핑 완료 · 수정':'색상 매핑하기';} $('headerBrand').textContent=S.job?.brand||'';$('headerState').replaceWith(Object.assign(status(S.job?.state||'WAITING'),{id:'headerState'}))}
function renderMonitor(){hide('monitorEmpty',!!S.job);hide('monitorBody',!S.job);if(!S.job){$('monitorName').textContent='실행 모니터';$('monitorSubtitle').textContent='현재 진행 중인 작업이 없습니다. 작업을 검색하면 과거 내역과 로그를 볼 수 있습니다.';return}const j=S.job;$('monitorName').textContent=j.name;$('monitorSubtitle').textContent=j.brand+' · '+(j.demo?'샘플 실행':'실제 크롤링')+' · '+date(j.created_at);$('monitorState').replaceWith(Object.assign(status(j.state),{id:'monitorState'}));const percent=Math.floor(j.done/Math.max(j.total,1)*100);$('monitorPercent').textContent=percent+'%';$('progress').value=percent;$('monitorStage').textContent=j.stage;$('monitorStats').replaceChildren(metric('전체 품번',j.total,j.skipped?'제외 '+j.skipped+'개 빼고':'입력 행 기준'),metric('성공',j.success,'결과 생성 완료','success'),metric('실패',j.failed,'오류 / 결과 없음','warning'),metric('대기',j.waiting,'미처리 품번'),metric('경과 시간',time(j.elapsed),'평균 '+time(j.average)),metric('예상 잔여',j.eta===null?'—':time(j.eta),j.eta===null?'3개 처리 후 추정':'최근 처리 속도 기준'));$('pause').disabled=!['running','pausing','paused'].includes(j.state);$('editTargets').disabled=!j.editable_targets;$('pause').textContent=['pausing','paused'].includes(j.state)?'▶ 재개':'Ⅱ 일시정지';$('stop').disabled=!['running','pausing','paused'].includes(j.state);const startReason=S.concurrency?.availability?.[j.brand_id]?.reason||'';$('continueJob').disabled=active()||!j.can_continue||!!startReason;$('retryFailed').disabled=active()||!j.can_retry||!!startReason;$('continueJob').title=$('retryFailed').title=active()?'':startReason;$('saveStatus').textContent=j.save_error|| (j.saved_at?'엑셀 저장 완료 · '+date(j.saved_at):'수신 행은 로컬 저널에 즉시 보존 · 엑셀 저장 대기');$('saveStatus').style.color=j.save_error?'#c34c4c':'';$('logDownload').href='/api/jobs/'+S.jobId+'/log-file'}
function pager(id,total,offset,limit,onPage){$(id).replaceChildren();$(id).append(el('span',total?Math.min(offset+1,total)+'–'+Math.min(offset+limit,total)+' / '+total:'0개'));const actions=el('div');const prev=button('이전',()=>onPage(Math.max(0,offset-limit))),next=button('다음',()=>onPage(offset+limit));prev.disabled=offset===0;next.disabled=offset+limit>=total;actions.append(prev,next);$(id).append(actions)}
async function loadQueue(force=false){if(!S.jobId)return;const key=[S.job?.queue_revision,S.job?.revision,$('queueSearch').value,$('queueFilter').value,S.queueOffset].join(':');if(!force&&key===S.queueKey)return;S.queueKey=key;const jid=S.jobId;const q=new URLSearchParams({search:$('queueSearch').value,status:$('queueFilter').value,offset:S.queueOffset,limit:50});const d=await api('/api/jobs/'+jid+'/queue?'+q);if(jid!==S.jobId||key!==S.queueKey)return;S.queue=d.rows;$('queueCount').textContent=d.total;$('queueRows').replaceChildren();for(const r of d.rows){let tr=el('tr',undefined,'clickable'+(S.queueTask===r.id?' selected':'')),cell=el('td');cell.append(status(r.status));tr.append(el('td',String(r.source_row??'—')),el('td',r.code),cell,el('td',r.result_ids.length+'개'),el('td',r.duration?time(r.duration):'—'));tr.onclick=run(()=>selectQueue(r));$('queueRows').append(tr)}if(!d.total){const tr=el('tr'),td=el('td','조건에 맞는 품번이 없습니다.');td.colSpan=5;tr.append(td);$('queueRows').append(tr)}pager('queuePager',d.total,S.queueOffset,50,async n=>{S.queueOffset=n;await loadQueue(true)});if(S.queueTask!==null){const r=d.rows.find(x=>x.id===S.queueTask);if(r)await selectQueue(r,false)}}
async function selectQueue(r,redraw=true){const jid=S.jobId;S.queueTask=r.id;$('monitorContext').replaceChildren();$('monitorContext').className='context-info';$('monitorContext').append(el('b',r.code),document.createElement('br'),status(r.status));if(r.error)$('monitorContext').append(el('p',r.error));if(r.result_ids.length){const item=await api('/api/jobs/'+S.jobId+'/items/'+r.result_ids[0]);if(jid!==S.jobId||S.queueTask!==r.id)return;if(item.main_images[0]){const img=el('img',undefined,'context-thumb');img.src=item.main_images[0];img.alt='대표이미지';img.referrerPolicy='no-referrer';$('monitorContext').append(img)}$('monitorContext').append(el('p',item.name||'상품명 미수집'),el('p','수집 결과 '+r.result_ids.length+'개'),button('결과 검수에서 열기 ↗',async()=>{S.reviewId=r.result_ids[0];S.reviewOffset=Math.floor(Number(S.reviewId)/50)*50;await navigate('review')}))}else $('monitorContext').append(el('p','아직 생성된 결과가 없습니다.'));if(redraw)S.queueKey=''}
async function jobAction(action,id=S.jobId){if(!id)throw Error('먼저 작업을 선택해주세요.');const d=await api('/api/jobs/'+id+'/'+action,{});if(['continue','retry-failed'].includes(action)){S.reviewId=null;S.item=null;S.queueKey=S.reviewKey='';toast(action==='continue'?'완료한 품번은 제외하고 이어 실행합니다.':'실패한 품번만 다시 실행합니다.');}if(action==='save')toast('처리로그를 포함한 엑셀을 로컬 폴더에 저장했습니다.');if(id===S.jobId){const job=await api('/api/jobs/'+id);if(id===S.jobId){S.job=job;renderHeader();renderMonitor()}}await refreshConcurrency();return d}
async function loadLogs(){if(!S.jobId||!$('logPanel').open)return;const jid=S.jobId;const q=new URLSearchParams({search:$('logSearch').value,level:$('logFilter').value,offset:S.logOffset,limit:100});const d=await api('/api/jobs/'+jid+'/logs?'+q);if(jid!==S.jobId)return;$('logs').replaceChildren(...d.rows.map(r=>{const line=el('div',undefined,'log-line');line.append(el('time',date(r.time)),el('span',r.level||'INFO','log-level '+r.level),el('span',r.text));return line}));pager('logPager',d.total,S.logOffset,100,async n=>{S.logOffset=n;await loadLogs()})}
async function loadReview(force=false){if(!S.jobId){empty($('reviewRows'),'작업을 선택하세요','작업 이력에서 결과를 열 수 있습니다.');return}const key=[S.job?.revision,S.job?.state,S.job?.queue_revision,$('reviewSearch').value,$('reviewFilter').value,S.reviewOffset].join(':');if(!force&&key===S.reviewKey)return;S.reviewKey=key;const jid=S.jobId;const q=new URLSearchParams({search:$('reviewSearch').value,status:$('reviewFilter').value,offset:S.reviewOffset,limit:50});const d=await api('/api/jobs/'+jid+'/items?'+q);if(jid!==S.jobId||key!==S.reviewKey)return;S.reviewRows=d.rows;S.reviewTotal=d.total;$('reviewTotal').textContent=d.total;$('reviewRows').replaceChildren();for(const r of d.rows){const b=button('',()=>selectResult(r.id),'review-row'+(r.id===S.reviewId?' selected':''));b.append(el('span',r.code,'code'),el('span',r.name||'상품명 미수집','name'));const meta=el('span',undefined,'meta');meta.append(status(r.status),el('span',r.image_count+'개 이미지'));b.append(meta);$('reviewRows').append(b)}pager('reviewPager',d.total,S.reviewOffset,50,async n=>{S.reviewOffset=n;S.reviewId=null;await loadReview(true)});if(!d.total){empty($('reviewRows'),'표시할 결과가 없어요','검색어·필터 또는 실행 상태를 확인하세요.');if(!S.reviewId){S.item=null;$('reviewName').textContent='표시할 결과 없음';$('reviewCode').textContent='수집 결과';$('reviewInfo').replaceChildren();empty($('reviewContent'),'표시할 결과가 없어요','생성된 상품 결과가 이곳에 표시됩니다.')}}else if(!S.reviewId||!S.item){await selectResult(S.reviewRows.find(x=>x.id===S.reviewId)?.id||S.reviewRows[0].id)}updateReviewNav()}
function updateReviewNav(){const idx=S.reviewRows.findIndex(x=>x.id===S.reviewId);$('previousProduct').disabled=idx<=0&&S.reviewOffset===0;$('nextProduct').disabled=idx<0||idx>=S.reviewRows.length-1&&S.reviewOffset+S.reviewRows.length>=S.reviewTotal;$('reviewExport').disabled=!S.jobId}
