function segmentHitsPhoto(x0,y0,x1,y1,rect){let near=0,far=1;for(const [a,b,min,max] of [[x0,x1,rect.left,rect.right],[y0,y1,rect.top,rect.bottom]]){const delta=b-a;if(Math.abs(delta)<.00001){if(a<min||a>max)return false;continue}const first=(min-a)/delta,last=(max-a)/delta;near=Math.max(near,Math.min(first,last));far=Math.min(far,Math.max(first,last));if(near>far)return false}return true;}
