async function openTargets(){if(!S.jobId)throw Error('먼저 작업을 선택해주세요.');const d=await api('/api/jobs/'+S.jobId+'/targets');T.rows=d.rows;T.edits={};T.skip=new Set();T.restore=new Set();$('targetsAdd').value='';$('targetsSearch').value='';$('targetsFilter').value='editable';
 const j=d.job,running=['running','pausing'].includes(j.state);
 $('targetsNotice').textContent=(j.state==='paused'?'일시정지 중입니다. 저장한 뒤 ▶ 재개하면 바뀐 목록으로 이어서 수집합니다.':running?'수집 중에도 아직 시작하지 않은 품번은 바꿀 수 있습니다. 안전하게 고치려면 먼저 일시정지하세요.':'작업이 끝난 상태입니다. 저장한 뒤 [남은 품번 이어하기]로 새 품번·수정한 품번만 수집합니다.')+' 수집 중인 품번과 완료된 품번은 그대로 둡니다. 실패·중지 품번을 고치면 이전 부분 결과는 지우고 다시 수집합니다.';
 $('targetsAddHint').textContent=(d.headers?.length>1?'엑셀에서 '+d.headers.join(' / ')+' 열을 그대로 복사해 붙여 넣기(탭 구분)':'한 줄에 하나씩')+' · 이미 목록에 있는 품번은 건너뜀';
 renderTargets();renderTargetsSummary();$('targetsDialog').showModal()}
async function saveTargets(){const p=targetsPending();if(!p.any)return;if(p.skip&&!confirm('제외한 품번 '+p.skip+'개는 수집하지 않습니다. 실패·중지 품번의 부분 결과도 지웁니다. 계속할까요?'))return;
 $('targetsSave').disabled=true;try{const d=await api('/api/jobs/'+S.jobId+'/targets',{add:$('targetsAdd').value,edit:Object.entries(T.edits).map(([id,code])=>({id,code})),skip:[...T.skip],restore:[...T.restore]});
  S.job=d.job;T.rows=d.rows;$('targetsDialog').close();renderHeader();renderMonitor();S.queueKey='';await loadQueue(true);
  const parts=[d.added&&'추가 '+d.added,d.edited&&'수정 '+d.edited,d.skipped&&'제외 '+d.skipped,d.restored&&'복원 '+d.restored].filter(Boolean).join(' · ');
  toast('대상 품번 저장 · '+parts+(d.duplicates.length?' · 중복 '+d.duplicates.length+'개 건너뜀':'')+(d.warnings.length?' · 형식 확인 필요 '+d.warnings.length+'개(로그)':'')+(['completed','stopped','interrupted','error'].includes(d.job.state)&&d.waiting?' · [남은 품번 이어하기]로 실행하세요':''))}
 finally{renderTargetsSummary()}}
$('editTargets').onclick=run(openTargets);$('targetsSave').onclick=run(saveTargets);$('targetsClose').onclick=$('targetsCancel').onclick=()=>$('targetsDialog').close();
$('targetsSearch').oninput=renderTargets;$('targetsFilter').onchange=renderTargets;$('targetsAdd').oninput=renderTargetsSummary;
